<?php
namespace App\Http\Controllers;
use App\Models\Project;
use App\Support\Decimal;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class GharController extends Controller {
 private function own(Request $r,Project $project):void {abort_unless($project->user_id===$r->user()->id,404);}
 public function projects(Request $r){return Project::where('user_id',$r->user()->id)->latest('id')->get();}
 public function createProject(Request $r){$v=$r->validate(['name'=>'required|string|max:120','location'=>'required|string|max:160','budget'=>['required','string','regex:/^\d{1,8}(?:\.\d{1,2})?$/D']]);$p=new Project(['name'=>$v['name'],'location'=>$v['location'],'budget_paisa'=>Decimal::scaled($v['budget'],2)]);$p->user_id=$r->user()->id;$p->save();return response()->json($p,201);}
 public function detail(Request $r,Project $project){$this->own($r,$project);$materials=DB::table('materials')->where('project_id',$project->id)->orderByDesc('id')->get();return ['project'=>$project,'materials'=>$materials,'material_total_paisa'=>$materials->sum('total_paisa'),'logs'=>DB::table('daily_logs')->where('project_id',$project->id)->orderByDesc('recorded_on')->get(),'consultations'=>DB::table('consultations')->where('project_id',$project->id)->orderBy('requested_at')->get()];}
 public function material(Request $r,Project $project){$this->own($r,$project);$v=$r->validate(['name'=>'required|string|max:100','supplier'=>'required|string|max:120','unit'=>['required',Rule::in(['bag','kg','tonne','piece','cft','sqft','m3'])],'quantity'=>['required','string','regex:/^\d{1,6}(?:\.\d{1,3})?$/D'],'rate'=>['required','string','regex:/^\d{1,7}(?:\.\d{1,2})?$/D'],'recorded_on'=>'required|date_format:Y-m-d']);$q=Decimal::scaled($v['quantity'],3);$rate=Decimal::scaled($v['rate'],2);abort_if($q===0||$rate===0,422,'Quantity and rate must be positive.');$id=DB::table('materials')->insertGetId(['project_id'=>$project->id,'name'=>$v['name'],'supplier'=>$v['supplier'],'unit'=>$v['unit'],'quantity_milli'=>$q,'rate_paisa'=>$rate,'total_paisa'=>Decimal::total($q,$rate),'recorded_on'=>$v['recorded_on'],'created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('materials')->find($id),201);}
 public function log(Request $r,Project $project){$this->own($r,$project);$v=$r->validate(['client_uuid'=>'required|uuid','recorded_on'=>'required|date_format:Y-m-d','notes'=>'required|string|max:5000']);$data=['project_id'=>$project->id,...$v,'created_at'=>now(),'updated_at'=>now()];$created=DB::table('daily_logs')->insertOrIgnore($data);$row=DB::table('daily_logs')->where('project_id',$project->id)->where('client_uuid',$v['client_uuid'])->first();abort_if(!$row,500);abort_if($row->notes!==$v['notes']||$row->recorded_on!==$v['recorded_on'],409,'This offline entry already exists with different content.');return response()->json($row,$created?201:200);}
 public function consultation(Request $r,Project $project){$this->own($r,$project);$v=$r->validate(['topic'=>'required|string|max:160','mode'=>['required',Rule::in(['video','in-person'])],'requested_at'=>'required|date|after:now']);$v['requested_at']=\Carbon\Carbon::parse($v['requested_at'])->utc()->toIso8601String();$id=DB::table('consultations')->insertGetId(['project_id'=>$project->id,...$v,'status'=>'requested','created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('consultations')->find($id),201);}
}
